import sys

def lnds(sub):
    if not sub:
        return 0
    dp = [1] * len(sub)
    for i in range(1, len(sub)):
        for j in range(i):
            if sub[i] >= sub[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def solve(s):
    n = len(s)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for l in range(n - 1, -1, -1):
        for r in range(l + 1, n + 1):
            dp[l][r] = lnds(s[l:r])

    def backtrack(l, r, zeros):
        if l == r:
            return '0' if zeros > 0 else '1'
        if dp[l][r] == dp[l + 1][r]:
            return '0' + backtrack(l + 1, r, zeros - 1)
        if dp[l][r] == dp[l][r - 1]:
            return backtrack(l, r - 1, zeros)
        if dp[l][r] == dp[l + 1][r - 1] + 1 and s[l] <= s[r - 1]:
            return '0' + backtrack(l + 1, r - 1, zeros - 1) if zeros > 0 else '1' + backtrack(l + 1, r - 1, zeros)
        return '1' + backtrack(l + 1, r, zeros)

    max_zeros = sum(c == '0' for c in s)
    return backtrack(0, n, max_zeros)

s = sys.stdin.read().strip()
print(solve(s))
